!> Constructs a modified Givens plane rotation.
!
!! ## Notes
!!
!! * Modified version of reference BLAS level1 routine (version 3.7.0). Updated to "free form" Fortran 95.
!!
!! ## Authors
!!
!! * Univ. of Tennessee
!! * Univ. of California Berkeley
!! * Univ. of Colorado Denver
!! * NAG Ltd.
!!
!! ## License
!!
!! From <http://netlib.org/blas/faq.html>:
!!
!! > The reference BLAS is a freely-available software package. It is available from netlib via anonymous ftp and the World Wide Web. Thus, it can be included in commercial software packages (and has been). We only ask that proper credit be given to the authors.
!! >
!! > Like all software, it is copyrighted. It is not trademarked, but we do ask the following:
!! >
!! > * If you modify the source for these routines we ask that you change the name of the routine and comment the changes made to the original.
!! >
!! > * We will gladly answer any questions regarding the software. If a modification is done, however, it is the responsibility of the person who modified the routine to provide support.
!
! @param {real} sd1 - scaling factor for the first vector component
! @param {real} sd2 - scaling factor for the second vector component
! @param {real} sx1 - first component of the first vector
! @param {real} sy1 - first component of the second vector
! @param {real} sparam - output array (dimension 5)
!<
subroutine srotmg( sd1, sd2, sx1, sy1, sparam )
  implicit none
  ! ..
  ! Internal parameters:
  integer, parameter :: wp = kind(1.e0)
  ! ..
  ! Constants:
  real(wp), parameter :: zero = 0.0e0_wp
  real(wp), parameter :: one  = 1.0e0_wp
  real(wp), parameter :: two  = 2.0e0_wp
  real(wp), parameter :: gam = 4096.0e0_wp
  real(wp), parameter :: gamsq = 1.67772e7_wp
  real(wp), parameter :: rgamsq = 5.96046e-8_wp
  ! ..
  ! Scalar Arguments:
  real(wp) :: sd1, sd2, sx1, sy1
  ! ..
  ! Array Arguments:
  real(wp) :: sparam(5)
  ! ..
  ! Local Scalars:
  real(wp) :: sflag, sh11, sh12, sh21, sh22, sp1, sp2, sq1, sq2, stemp, su
  ! Initialize h variables to zero to avoid uninitialized warnings:
  sh11 = zero
  sh12 = zero
  sh21 = zero
  sh22 = zero
  ! ..
  if ( sd1 .lt. zero ) then
    ! GO ZERO-H-D-AND-SX1..
    sflag = -one
    sh11 = zero
    sh12 = zero
    sh21 = zero
    sh22 = zero

    sd1 = zero
    sd2 = zero
    sx1 = zero
  else
    ! CASE-SD1-NONNEGATIVE
    sp2 = sd2 * sy1
    if ( sp2 .eq. zero ) then
      sflag = -two
      sparam(1) = sflag
      return
    end if
    ! REGULAR-CASE..
    sp1 = sd1 * sx1
    sq2 = sp2 * sy1
    sq1 = sp1 * sx1

    if ( abs(sq1) .gt. abs(sq2) ) then
      sh21 = -sy1 / sx1
      sh12 = sp2 / sp1

      su = one - sh12 * sh21

      if ( su .gt. zero ) then
        sflag = zero
        sd1 = sd1 / su
        sd2 = sd2 / su
        sx1 = sx1 * su
      else
        ! This code path if here for safety. We do not expect this
        ! condition to ever hold except in edge cases with rounding
        ! errors. See DOI: 10.1145/355841.355847
        sflag = -one
        sh11 = zero
        sh12 = zero
        sh21 = zero
        sh22 = zero

        sd1 = zero
        sd2 = zero
        sx1 = zero
      end if
    else
      if ( sq2 .lt. zero ) then
        ! GO ZERO-H-D-AND-SX1..
        sflag = -one
        sh11 = zero
        sh12 = zero
        sh21 = zero
        sh22 = zero

        sd1 = zero
        sd2 = zero
        sx1 = zero
      else
        sflag = one
        sh11 = sp1 / sp2
        sh22 = sx1 / sy1
        su = one + sh11 * sh22
        stemp = sd2 / su
        sd2 = sd1 / su
        sd1 = stemp
        sx1 = sy1 * su
      end if
    end if

    ! PROCEDURE..SCALE-CHECK
    if ( sd1 .ne. zero ) then
      do while ( (sd1 .le. rgamsq) .or. (sd1 .ge. gamsq) )
        if ( sflag .eq. zero ) then
          sh11 = one
          sh22 = one
          sflag = -one
        else
          sh21 = -one
          sh12 = one
          sflag = -one
        end if
        if ( sd1 .le. rgamsq ) then
          sd1 = sd1 * gam**2
          sx1 = sx1 / gam
          sh11 = sh11 / gam
          sh12 = sh12 / gam
        else
          sd1 = sd1 / gam**2
          sx1 = sx1 * gam
          sh11 = sh11 * gam
          sh12 = sh12 * gam
        end if
      end do
    end if

    if ( sd2 .ne. zero ) then
      do while ( (abs(sd2) .le. rgamsq) .or. (abs(sd2) .ge. gamsq) )
        if ( sflag .eq. zero ) then
          sh11 = one
          sh22 = one
          sflag = -one
        else
          sh21 = -one
          sh12 = one
          sflag = -one
        end if
        if ( abs(sd2) .le. rgamsq ) then
          sd2 = sd2 * gam**2
          sh21 = sh21 / gam
          sh22 = sh22 / gam
        else
          sd2 = sd2 / gam**2
          sh21 = sh21 * gam
          sh22 = sh22 * gam
        end if
      end do
    end if
  end if

  if ( sflag .lt. zero ) then
    sparam(2) = sh11
    sparam(3) = sh21
    sparam(4) = sh12
    sparam(5) = sh22
  else if ( sflag .eq. zero ) then
    sparam(3) = sh21
    sparam(4) = sh12
  else
    sparam(2) = sh11
    sparam(5) = sh22
  end if

  sparam(1) = sflag
  return
end subroutine srotmg

